import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { StemDashboardPage } from './stem-dashboard.page';

const routes: Routes = [
  {
    path: '',
    component: StemDashboardPage
  },  {
    path: 'summary-attendance',
    loadChildren: () => import('./summary-attendance/summary-attendance.module').then( m => m.SummaryAttendancePageModule)
  }

];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class StemDashboardPageRoutingModule {}
